#LLM quality filter
import json, requests

RUBRIC = """You evaluate training data for a model that generates Revit API / Dynamo Python nodes.

A good record must:
- Be a Python script usable as a Dynamo node (uses IN[] for inputs, OUT for output)
- Use Revit API correctly (clr references, FilteredElementCollector patterns, etc.)
- Be self-contained and not truncated
- Be free of HTML or encoding garbage

Score as JSON only — no explanation outside the JSON:
{"relevance": 0-3, "correctness": 0-3, "completeness": 0-2, "clean": 0-2, "total": 0-10}"""

def score_local(prompt, completion, model="mistral"):
    r = requests.post("http://localhost:11434/api/chat", json={
        "model": model,
        "messages": [
            {"role": "system", "content": RUBRIC},
            {"role": "user", "content": f"PROMPT:\n{prompt[:500]}\n\nCOMPLETION:\n{completion[:1200]}"}
        ],
        "stream": False
    })
    try:
        return json.loads(r.json()["message"]["content"])
    except:
        return None

def filter_dataset(input_file, output_file, min_score=6, use_local=True):
    kept, dropped = 0, 0
    with open(input_file) as f_in, open(output_file, "w") as f_out:
        for line in f_in:
            record = json.loads(line)
            score = score_local(record["prompt"], record["completion"])
            if score and score.get("total", 0) >= min_score:
                record["_score"] = score
                f_out.write(json.dumps(record) + "\n")
                kept += 1
            else:
                dropped += 1

    print(f"Filter done — kept: {kept}, dropped: {dropped}")

#This script converts raw sources into training pairs; normalize into same prompt/completion schema
import json, re
from pathlib import Path
from bs4 import BeautifulSoup

def strip_html(text):
    return BeautifulSoup(text, "html.parser").get_text(separator="\n")

def extract_code_blocks(text):
    return re.findall(r'```(?:python)?(.*?)```', text, re.DOTALL)

def extract_inline_code(text):
    """Fallback: grab indented blocks that look like Python nodes."""
    blocks = re.findall(r'((?:(?:import clr|IN\[|OUT\s*=).*\n(?:.*\n){2,20})+)', text)
    return blocks

def format_as_training_pair(prompt, completion):
    """Enforce consistent structure."""
    completion = completion.strip()
    # ensure it has the Dynamo scaffolding
    if "IN[" not in completion and "OUT" not in completion:
        return None
    return {
        "prompt": prompt.strip()[:800],
        "completion": completion[:2000]
    }

def process_all(raw_dir, output_file):
    raw_dir = Path(raw_dir)
    pairs = []

    # --- Discourse ---
    for line in open(raw_dir / "raw_discourse.jsonl"):
        r = json.loads(line)
        question = strip_html(r["question"])
        for reply in r["replies"]:
            reply_text = strip_html(reply)
            for block in extract_code_blocks(reply_text):
                pair = format_as_training_pair(
                    f"{r['topic']}\n{question}", block
                )
                if pair:
                    pairs.append(pair)

    # --- StackOverflow ---
    for line in open(raw_dir / "raw_stackoverflow.jsonl"):
        r = json.loads(line)
        answer = strip_html(r["answer"])
        for block in extract_code_blocks(answer) or extract_inline_code(answer):
            pair = format_as_training_pair(r["question"], block)
            if pair:
                pairs.append(pair)

    # --- GitHub ---
    for line in open(raw_dir / "raw_github.jsonl"):
        r = json.loads(line)
        pair = format_as_training_pair(
            f"Dynamo Python node from {r['repo']} ({r['filename']})",
            r["content"]
        )
        if pair:
            pairs.append(pair)

    with open(output_file, "w") as f:
        for p in pairs:
            f.write(json.dumps(p) + "\n")

    # --- Revit 2023 API Docs ---
    if (raw_dir / "raw_apidocs.jsonl").exists():
        for line in open(raw_dir / "raw_apidocs.jsonl"):
            r = json.loads(line)
            # code examples become completions directly
            for example in r["examples"]:
                if len(example) > 80:
                    pair = format_as_training_pair(
                        f"Show example usage of the Revit API {r['class']} class",
                        example
                    )
                    if pair:
                        pairs.append(pair)
            # member descriptions become prompt/completion reference pairs
            if r["members"]:
                members_text = "\n".join(
                    f"{m['member']}: {m['description']}"
                    for m in r["members"][:20]
                )
                pairs.append({
                    "prompt": f"What are the members of the Revit API {r['class']} class?",
                    "completion": members_text
                })
    # --- Hand-crafted pairs (highest quality, skip quality filter) ---
    hand_crafted_path = raw_dir.parent.parent / "dataset" / "hand_crafted.jsonl"
    if hand_crafted_path.exists():
        hc_count = 0
        for line in open(hand_crafted_path):
            r = json.loads(line)
            pairs.append({
                "prompt": r["prompt"],
                "completion": r["completion"],
                "_score": {"total": 10, "source": "hand_crafted"}
            })
            hc_count += 1
        print(f"Hand-crafted pairs loaded: {hc_count}")            

    print(f"Formatted: {len(pairs)} training pairs")
    return len(pairs)

import requests, json, time
from pathlib import Path

BASE = "https://forum.dynamobim.com"

def scrape(output_dir, pages=30):
    Path(output_dir).mkdir(exist_ok=True)
    results = []

    for page in range(pages):
        topics = requests.get(
            f"{BASE}/latest.json?page={page}",
            headers={"User-Agent": "ResearchBot/1.0"}
        ).json().get("topic_list", {}).get("topics", [])

        for topic in topics:
            try:
                data = requests.get(
                    f"{BASE}/t/{topic['id']}.json",
                    headers={"User-Agent": "ResearchBot/1.0"}
                ).json()
                posts = data.get("post_stream", {}).get("posts", [])
                if len(posts) < 2:
                    continue

                # only keep threads with Python code
                full_text = " ".join(p.get("cooked", "") for p in posts)
                if "import clr" not in full_text and "IN[" not in full_text:
                    continue

                results.append({
                    "source": "dynamo_forum",
                    "topic": topic.get("title", ""),
                    "question": posts[0].get("cooked", ""),
                    "replies": [p.get("cooked", "") for p in posts[1:5]]
                })
                time.sleep(1)
            except Exception as e:
                print(f"  Error topic {topic['id']}: {e}")

        print(f"Discourse page {page}: {len(results)} records so far")
        time.sleep(2)

    out = Path(output_dir) / "raw_discourse.jsonl"
    with open(out, "w") as f:
        for r in results:
            f.write(json.dumps(r) + "\n")
    print(f"Discourse done: {len(results)} records")

# tools/pptx_scraper.py
import json
import os
import re
import shutil
import subprocess
import time
import zipfile
import requests
from pathlib import Path
from datetime import datetime

try:
    from pptx import Presentation
except ImportError:
    print("ERROR: python-pptx not installed. Run: pip install python-pptx")
    exit(1)

# Paths
RAW_DIR      = Path("dataset/pptx/raw")
APPROVED_DIR = Path("dataset/pptx/approved")
CLONE_DIR    = Path("dataset/pptx/cloned_repos")
PROGRESS_LOG = Path("dataset/pptx/progress_log.json")

for d in [RAW_DIR, APPROVED_DIR, CLONE_DIR]:
    d.mkdir(parents=True, exist_ok=True)

OLLAMA_URL   = "http://localhost:11434/api/chat"
JUDGE_MODEL  = "mistral"
MIN_SCORE    = 5

# Single-Pass System Prompt
SINGLE_PASS_SYSTEM = """You extract training data for a Revit API and Dynamo Python code model.
Analyze the PowerPoint slide content. If it contains technical Revit/Dynamo concepts, score its relevance (0-10) and extract 1-2 training pairs.
Pairs must use the Dynamo IN[]/OUT pattern and include clr.AddReference('RevitAPI').

Return ONLY valid JSON in this exact format:
{
  "score": <0-10>,
  "reason": "<brief justification>",
  "pairs": [
    {"prompt": "<clear question/task>", "completion": "<python code>"}
  ]
}
If no extractable code exists, return {"score": 0, "reason": "No technical content", "pairs": []}"""

def load_progress():
    if PROGRESS_LOG.exists():
        with open(PROGRESS_LOG, "r") as f:
            return set(json.load(f))
    return set()

def save_progress(processed_files):
    with open(PROGRESS_LOG, "w") as f:
        json.dump(list(processed_files), f, indent=4)

def extract_pptx(pptx_path: Path) -> list[dict]:
    slides = []
    try:
        prs = Presentation(str(pptx_path))
        for i, slide in enumerate(prs.slides):
            text_parts = []
            for shape in slide.shapes:
                if shape.has_text_frame:
                    for para in shape.text_frame.paragraphs:
                        if para.text.strip(): text_parts.append(para.text.strip())

            notes = slide.notes_slide.notes_text_frame.text.strip() if slide.has_notes_slide and slide.notes_slide.notes_text_frame else ""
            slide_text = "\n".join(text_parts)

            if slide_text or notes:
                slides.append({
                    "slide_number": i + 1,
                    "combined": f"{slide_text}\n\nSpeaker notes:\n{notes}" if notes else slide_text
                })
    except Exception as e:
        print(f"    Error reading {pptx_path.name}: {e}")
    return slides

def process_slide_single_pass(slide_content: str, source_name: str) -> dict:
    try:
        r = requests.post(OLLAMA_URL, json={
            "model": JUDGE_MODEL,
            "messages": [
                {"role": "system", "content": SINGLE_PASS_SYSTEM},
                {"role": "user", "content": f"SOURCE: {source_name}\n\nSLIDE CONTENT:\n{slide_content[:1500]}"}
            ],
            "stream": False
        }, timeout=120)
        content = r.json()["message"]["content"]
        match = re.search(r'\{.*\}', content, re.DOTALL)
        if match:
            return json.loads(match.group())
    except Exception as e:
        print(f"    Mistral error: {e}")
    return {"score": 0, "pairs": []}

def process_pptx(pptx_path: Path, processed_files: set) -> dict:
    safe_name = re.sub(r'[^\w]', '_', pptx_path.stem)[:60]

    if safe_name in processed_files:
        print(f"  [SKIPPED] {pptx_path.name} (Already processed)")
        return {"file": pptx_path.name, "approved": 0}

    print(f"\n  [PROCESSING] {pptx_path.name}")
    slides = extract_pptx(pptx_path)

    if not slides:
        processed_files.add(safe_name)
        save_progress(processed_files)
        return {"file": pptx_path.name, "approved": 0}

    out_path = APPROVED_DIR / f"{safe_name}.jsonl"
    approved_pairs = []

    for idx, slide in enumerate(slides):
        print(f"    -> Slide {idx+1}/{len(slides)}", end="\r")
        result = process_slide_single_pass(slide["combined"], pptx_path.name)

        if result.get("score", 0) >= MIN_SCORE:
            for pair in result.get("pairs", []):
                if pair.get("prompt") and pair.get("completion"):
                    record = {
                        "source": "pptx",
                        "file": pptx_path.name,
                        "slide": slide["slide_number"],
                        "prompt": pair["prompt"],
                        "completion": pair["completion"],
                        "date_added": datetime.now().strftime("%Y-%m-%d")
                    }
                    approved_pairs.append(record)
                    with open(out_path, "a", encoding="utf-8") as f:
                        f.write(json.dumps(record) + "\n")

    processed_files.add(safe_name)
    save_progress(processed_files)
    print(f"    [DONE] Extracted {len(approved_pairs)} valid pairs.    ")
    return {"file": pptx_path.name, "approved": len(approved_pairs)}

def main():
    print("=" * 60)
    print(f" PowerPoint Scraper | Model: {JUDGE_MODEL}")
    print("=" * 60)

    processed_files = load_progress()
    raw = input("\nPath to .pptx file or folder (or 'q' to quit): ").strip().strip('"')
    if raw.lower() == 'q': return

    path = Path(raw)
    files = [path] if path.is_file() and path.suffix.lower() == ".pptx" else sorted(path.rglob("*.pptx"))

    to_process = [f for f in files if re.sub(r'[^\w]', '_', f.stem)[:60] not in processed_files]
    print(f"\nFound {len(files)} files. ({len(files) - len(to_process)} already processed)")

    total_approved = 0
    for pptx_path in to_process:
        res = process_pptx(pptx_path, processed_files)
        total_approved += res.get("approved", 0)

    print("\n" + "=" * 60)
    print(f" Session Complete | High-confidence pairs: {total_approved}")
    print("=" * 60)

if __name__ == "__main__":
    main()

import requests
import json
import time
import logging
from pathlib import Path

API = "https://api.stackexchange.com/2.3"

# Set up logging
logging.basicConfig(filename='scraping.log', level=logging.INFO)

def scrape(output_dir, api_key, pages=15):
    Path(output_dir).mkdir(exist_ok=True)
    results = []

    # target both tags — they have different but overlapping communities
    for tag in ["revit-api", "dynamo-revit"]:
        for page in range(1, pages + 1):
            try:
                qs = requests.get(f"{API}/questions", params={
                    "order": "desc", "sort": "votes",
                    "tagged": tag, "site": "stackoverflow",
                    "filter": "withbody", "pagesize": 100,
                    "page": page, "key": api_key
                }).json().get("items", [])
            except requests.RequestException as e:
                logging.error(f"Error fetching questions for tag {tag} on page {page}: {e}")
                continue

            for q in qs:
                if q.get("answer_count", 0) == 0:
                    continue
                try:
                    answers = requests.get(
                        f"{API}/questions/{q['question_id']}/answers",
                        params={"order": "desc", "sort": "votes",
                                "site": "stackoverflow", "filter": "withbody",
                                "key": api_key}
                    ).json().get("items", [])
                except requests.RequestException as e:
                    logging.error(f"Error fetching answers for question {q['question_id']}: {e}")
                    continue

                top = next((a for a in answers if a.get("score", 0) > 1), None)
                if not top:
                    continue

                results.append({
                    "source": "stackoverflow",
                    "tag": tag,
                    "question": q["title"] + "\n" + q.get("body", ""),
                    "answer": top.get("body", ""),
                    "score": top.get("score", 0)
                })
                time.sleep(0.5)

            logging.info(f"SO [{tag}] page {page}: {len(results)} total")
            time.sleep(1)

    out = Path(output_dir) / "raw_stackoverflow.jsonl"
    with open(out, "w", encoding="utf-8") as f:
        for r in results:
            f.write(json.dumps(r) + "\n")
    logging.info(f"StackOverflow done: {len(results)} records")

"""
repo_snapshot.py
Dumps a structured JSON snapshot of the repository for AI review.
Includes: directory tree, file metadata, and contents of all script files.
Run from the repo root. Output: repo_snapshot.json
"""

import json
from datetime import datetime
from pathlib import Path

# ── Configuration ─────────────────────────────────────────────────────────────

# Extensions whose contents will be included verbatim
CONTENT_EXTENSIONS = {".py", ".yaml", ".yml", ".md", ".txt", ".bat"}

# Filenames to skip entirely
SKIP_FILES = {
    "repo_snapshot.py",
    "repo_snapshot.json",
    "RepoMapper.py",
    ".gitignore",
    ".gitattributes",
}

# Directory NAMES (not paths) to skip entirely — matched against entry.name only
SKIP_DIRS = {
    ".git",
    ".venv",
    "__pycache__",
    "node_modules",
    ".continue",
    ".vscode",
    "temp_chm_extract",
}

# Directory NAMES whose contents are collapsed to a file-count summary
# — avoids listing thousands of SDK records individually
COLLAPSE_DIRS = {
    "Classes",
    "Enums",
    "cloned_repos",
}

# Max file size to read content (bytes)
MAX_CONTENT_BYTES = 100_000


# ── Helpers ───────────────────────────────────────────────────────────────────

def should_include_content(path: Path) -> bool:
    if path.suffix not in CONTENT_EXTENSIONS:
        return False
    try:
        if path.stat().st_size > MAX_CONTENT_BYTES:
            return False
    except OSError:
        return False
    return True


def read_file(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8", errors="replace")
    except Exception as e:
        return f"[READ ERROR: {e}]"


def count_lines(path: Path) -> int:
    try:
        return sum(1 for _ in path.open(encoding="utf-8", errors="replace"))
    except Exception:
        return -1


def summarise_dir(path: Path) -> dict:
    """Count files by extension without recursing into the tree output."""
    counts: dict[str, int] = {}
    try:
        for f in path.rglob("*"):
            if f.is_file():
                ext = f.suffix or "(no ext)"
                counts[ext] = counts.get(ext, 0) + 1
    except PermissionError:
        pass
    total = sum(counts.values())
    return {
        "type": "directory",
        "name": path.name,
        "collapsed": True,
        "reason": "bulk data directory — summarised only",
        "total_files": total,
        "file_counts_by_extension": dict(sorted(counts.items())),
    }


# ── Tree builder ──────────────────────────────────────────────────────────────

def build_tree(root: Path) -> dict:
    node = {
        "type": "directory",
        "name": root.name,
        "children": [],
    }

    try:
        # dirs first, then files, each group sorted alphabetically
        entries = sorted(root.iterdir(), key=lambda p: (p.is_file(), p.name.lower()))
    except PermissionError:
        return node

    for entry in entries:
        if entry.is_dir():
            name = entry.name
            if name in SKIP_DIRS:
                node["children"].append({
                    "type": "directory",
                    "name": name,
                    "skipped": True,
                    "reason": "excluded from snapshot",
                })
            elif name in COLLAPSE_DIRS:
                node["children"].append(summarise_dir(entry))
            else:
                node["children"].append(build_tree(entry))

        elif entry.is_file():
            if entry.name in SKIP_FILES:
                continue

            try:
                size = entry.stat().st_size
            except OSError:
                size = -1

            file_node: dict = {
                "type": "file",
                "name": entry.name,
                "extension": entry.suffix,
                "size_bytes": size,
            }

            if should_include_content(entry):
                file_node["lines"] = count_lines(entry)
                file_node["content"] = read_file(entry)
            else:
                file_node["content_included"] = False
                if entry.suffix == ".jsonl":
                    file_node["skip_reason"] = "jsonl data file"
                elif entry.suffix == ".json":
                    file_node["skip_reason"] = "json data file"
                elif size > MAX_CONTENT_BYTES:
                    file_node["skip_reason"] = f"file too large ({size:,} bytes)"
                else:
                    file_node["skip_reason"] = "binary or non-script file"

            node["children"].append(file_node)

    return node


# ── Stats collector ───────────────────────────────────────────────────────────

def collect_stats(root: Path) -> dict:
    """Walk the same subset of files that build_tree visits."""
    total_files = 0
    total_dirs = 0
    py_files = 0
    jsonl_files = 0
    content_files = 0

    def _walk(path: Path):
        nonlocal total_files, total_dirs, py_files, jsonl_files, content_files
        try:
            entries = list(path.iterdir())
        except PermissionError:
            return
        for entry in entries:
            if entry.is_dir():
                name = entry.name
                if name in SKIP_DIRS or name in COLLAPSE_DIRS:
                    continue
                total_dirs += 1
                _walk(entry)
            elif entry.is_file():
                if entry.name in SKIP_FILES:
                    continue
                total_files += 1
                if entry.suffix == ".py":
                    py_files += 1
                elif entry.suffix == ".jsonl":
                    jsonl_files += 1
                if should_include_content(entry):
                    content_files += 1

    _walk(root)
    return {
        "total_files": total_files,
        "total_directories": total_dirs,
        "python_files": py_files,
        "jsonl_data_files": jsonl_files,
        "files_with_content_included": content_files,
    }


# ── Main ──────────────────────────────────────────────────────────────────────

def main():
    root = Path(__file__).parent.resolve()
    output_path = root / "repo_snapshot.json"

    print(f"Scanning: {root}")
    print("Building tree...")
    tree = build_tree(root)

    print("Collecting stats...")
    stats = collect_stats(root)

    snapshot = {
        "meta": {
            "generated_at": datetime.now().isoformat(),
            "repo_root": str(root),
            "purpose": (
                "AI review snapshot — full file tree and script contents for "
                "the starcoder-revitapi-python-dynamo-pipeline project. "
                "Script files (.py, .yaml, .md, .bat, .txt) are included verbatim. "
                "Data files (.jsonl, .json) listed without content. "
                "Bulk SDK directories (Classes/, Enums/) collapsed to file counts."
            ),
            "content_extensions_included": sorted(CONTENT_EXTENSIONS),
            "skipped_directories": sorted(SKIP_DIRS),
            "collapsed_directories": sorted(COLLAPSE_DIRS),
            "stats": stats,
        },
        "tree": tree,
    }

    print(f"Writing {output_path.name}...")
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(snapshot, f, indent=2, ensure_ascii=False)

    size_kb = output_path.stat().st_size / 1024
    print(f"\nDone. {output_path.name} — {size_kb:.1f} KB")
    print(f"  Total files scanned:    {stats['total_files']}")
    print(f"  Python files:           {stats['python_files']}")
    print(f"  Files with content:     {stats['files_with_content_included']}")
    print(f"  JSONL data files:       {stats['jsonl_data_files']} (listed, no content)")


if __name__ == "__main__":
    main()
